package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.enums.StatusAtivo;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.*; import java.util.UUID;
@Entity @Table(name="cliente") public class ClienteEntity { @Id public UUID id; @Column(name="empresa_id",nullable=false) public UUID empresaId; @Column(nullable=false,length=160) public String nome; @Column(name="cpf_cnpj",length=18) public String cpfCnpj; @Column(length=255) public String email; @Column(length=30) public String telefone; @Column(name="data_nascimento") public LocalDate dataNascimento; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="status_ativo") public StatusAtivo status; @Column(name="created_at",nullable=false) public Instant criadoEm; @Column(name="updated_at",nullable=false) public Instant atualizadoEm; public ClienteEntity() {} }
